head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setFocusedHeaderObj]<br/>Header Column 의 ID 를 사용하여 특정 Header 에 포커스를 설정합니다.",
    "validation" : [
        "Header 의 인덱스를 사용할 경우 getHeaderID() 메소드로 ID 를 얻은 후 전달해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 기본값 설정 (초기 selectedIndex 미적용 대응)
    par_headerIndex.setSelectedIndex(0);

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - Header : hCheck(checkbox) / hSelect(select) / hCombo(checkcombobox) / hText(text)
//    -> 인덱스 0,1,2,3 에 대해 getHeaderID() 로 얻은 ID 를 전달하여 포커스 설정
scwin.comp_init = async function () {
    // 기존 target / dataList 있으면 삭제
    if (typeof dlt_item !== 'undefined') {
        $p.data.remove("dlt_item");
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 구성 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Header 는 인덱스 0,1,2,3 순서로 hCheck(checkbox) / hSelect(select) / hCombo(checkcombobox) / hText(text) 4종으로 구성\n[절차] headerIndex 를 선택하고 아래 버튼을 클릭\n[확인] 결과창에서 해당 인덱스로 얻은 Header ID 와 그 ID 로 설정된 (포커스된 요소) / (Header 영역 내부 포커스 여부) 를 확인"', '', 'label1');

    // 헤더 select / checkcombobox 아이템 DataList
    let strItem = '';
    strItem += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_item" baseNode="list" repeatNode="map">';
    strItem += '<w2:columnInfo>';
    strItem += '<w2:column id="iValue" name="iValue" dataType="text"></w2:column>';
    strItem += '<w2:column id="iLabel" name="iLabel" dataType="text"></w2:column>';
    strItem += '</w2:columnInfo>';
    strItem += '<w2:data use="true"></w2:data>';
    strItem += '</w2:dataList>';
    $p.data.create(strItem);
    dlt_item.setJSON([
        { "iValue": "A", "iLabel": "최우수" },
        { "iValue": "B", "iLabel": "우수" },
        { "iValue": "C", "iLabel": "보통" }
    ], false);

    // Body 데이터용 DataList
    let strDlt = '';
    strDlt += '<w2:dataList ' + $c.gcm.getNameSpace() + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="col1" name="col1" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col2" name="col2" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col3" name="col3" dataType="text"></w2:column>';
    strDlt += '<w2:column id="col4" name="col4" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "col1": "false", "col2": "A", "col3": "노트북", "col4": "재고확인" },
        { "col1": "false", "col2": "B", "col3": "모니터", "col4": "신규입고" },
        { "col1": "false", "col2": "C", "col3": "키보드", "col4": "할인적용" },
        { "col1": "false", "col2": "A", "col3": "마우스", "col4": "주문대기" }
    ], false);

    let grp_comp = $c.gcm.getTestGroup();
    let strNameSpace = $c.gcm.getNameSpace();

    // 헤더 아이템 바인딩 조각 (select / checkcombobox 헤더용)
    let itemset = '<w2:choices><w2:itemset nodeset="data:dlt_item"><w2:label ref="iLabel"></w2:label><w2:value ref="iValue"></w2:value></w2:itemset></w2:choices>';

    // target 생성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="include" id="" style="width:600px;height:240px;">';
    strTarget += '<w2:caption style="" id="caption1" value="setFocusedHeaderObj 테스트 그리드"></w2:caption>';
    strTarget += '<w2:header style="" id="header1"><w2:row style="" id="hrow1">';
    strTarget += '<w2:column width="110" inputType="checkbox" id="hCheck" value=""></w2:column>';
    strTarget += '<w2:column width="150" inputType="select" id="hSelect" value="">' + itemset + '</w2:column>';
    strTarget += '<w2:column width="170" inputType="checkcombobox" id="hCombo" value="">' + itemset + '</w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="hText" value="분류(text)"></w2:column>';
    strTarget += '</w2:row></w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1"><w2:row style="" id="brow1">';
    strTarget += '<w2:column width="110" inputType="checkbox" id="col1" dataList="col1"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="col2" dataList="col2" displayType="label"></w2:column>';
    strTarget += '<w2:column width="170" inputType="text" id="col3" dataList="col3" displayType="label"></w2:column>';
    strTarget += '<w2:column width="150" inputType="text" id="col4" dataList="col4" displayType="label"></w2:column>';
    strTarget += '</w2:row></w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// getHeaderID(headerIndex) 로 Header Column 의 ID 를 얻은 후 setFocusedHeaderObj 에 전달
//  - 실제 포커스된 요소(document.activeElement) 를 실측하고,
//    대상 Header 의 th 요소가 activeElement 를 포함하는지로 Header 포커스 여부를 판정
scwin.btn_setFocusedHeaderObj_onclick = function () {
    let headerIndex = Number(par_headerIndex.getValue());
    let bottom = wf_body_bottom.getObj("scwin");

    let headerId = target1.getHeaderID(headerIndex);
    target1.setFocusedHeaderObj(headerId);

    let th = target1.getHeaderLayer(headerId);
    let act = document.activeElement;

    let actDesc = "없음";
    if (act && act !== document.body) {
        let type = act.getAttribute("type");
        actDesc = act.tagName + (type ? "[type=" + type + "]" : "") + (act.className ? " (class=" + act.className + ")" : "");
        let ownerTh = act.closest("th");
        if (ownerTh) actDesc += " (소속 Header : " + ownerTh.id + ")";
    }

    let inHeader = !!(th && act && th.contains(act));

    bottom.setReturnValue("getHeaderID(" + headerIndex + ") : " + headerId + " 를 setFocusedHeaderObj 에 전달");
    bottom.setReturnValue("포커스된 요소 : " + actDesc + " / Header 영역 내부 포커스 여부 : " + inHeader);
}
